mapper.select:
SELECT C.CARD_ID, C.CARD_NM, C.COMPANY_NM, C.DEPT_NM, C.POSITION_NM, C.TEL_NO, C.REGIST_DT, CASE WHEN U.CARD_ID IS NULL THEN 'N' ELSE 'Y' END AS USED_YN FROM BUSINESS_CARD C LEFT JOIN CARD_USER U ON C.CARD_ID = U.CARD_ID AND U.USER_NM = #{userNm} WHERE C.OPEN_YN = 'Y'
AND (C.CARD_NM LIKE '%' || #{searchKeyword} || '%' OR C.COMPANY_NM LIKE '%' || #{searchKeyword} || '%' OR C.DEPT_NM LIKE '%' || #{searchKeyword} || '%')
ORDER BY C.REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT C.CARD_ID, C.CARD_NM, C.COMPANY_NM, C.DEPT_NM, C.POSITION_NM, C.TEL_NO, C.OPEN_YN, C.REGIST_DT FROM BUSINESS_CARD C WHERE C.REGISTER = #{userNm} OR EXISTS (SELECT 1 FROM CARD_USER U WHERE U.CARD_ID = C.CARD_ID AND U.USER_NM = #{userNm})
AND (C.CARD_NM LIKE '%' || #{searchKeyword} || '%' OR C.COMPANY_NM LIKE '%' || #{searchKeyword} || '%' OR C.DEPT_NM LIKE '%' || #{searchKeyword} || '%')
ORDER BY C.REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.delete:
DELETE FROM BUSINESS_CARD
WHERE CARD_ID = #{cardId}
	AND REGISTER = #{register}

DELETE FROM CARD_USER
WHERE CARD_ID = #{cardId}
	AND USER_NM = #{userNm}
